-- Permission center foundation. Legacy users remain the identity source; all new objects are cc_*.
CREATE TABLE IF NOT EXISTS cc_roles (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, role_code VARCHAR(80) NOT NULL, role_name VARCHAR(120) NOT NULL, data_scope VARCHAR(30) NOT NULL DEFAULT 'self', status VARCHAR(30) NOT NULL DEFAULT 'active', created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, PRIMARY KEY(id), UNIQUE KEY uq_cc_role_code(role_code)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cc_permissions (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, permission_code VARCHAR(160) NOT NULL, permission_name VARCHAR(190) NOT NULL, permission_type VARCHAR(30) NOT NULL DEFAULT 'action', parent_code VARCHAR(160) NULL, module_code VARCHAR(80) NULL, status VARCHAR(30) NOT NULL DEFAULT 'active', created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, PRIMARY KEY(id), UNIQUE KEY uq_cc_permission_code(permission_code), KEY idx_cc_permission_parent(parent_code)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cc_role_permissions (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, role_id BIGINT UNSIGNED NOT NULL, permission_id BIGINT UNSIGNED NOT NULL, effect VARCHAR(10) NOT NULL DEFAULT 'allow', created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, PRIMARY KEY(id), UNIQUE KEY uq_cc_role_permission(role_id,permission_id), KEY idx_cc_role_permission_effect(effect)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cc_user_roles (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, legacy_user_id INT UNSIGNED NOT NULL, role_id BIGINT UNSIGNED NOT NULL, department_id BIGINT UNSIGNED NULL, factory_id BIGINT UNSIGNED NULL, expires_at DATETIME NULL, status VARCHAR(30) NOT NULL DEFAULT 'active', created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, PRIMARY KEY(id), UNIQUE KEY uq_cc_user_role(legacy_user_id,role_id,department_id,factory_id), KEY idx_cc_user_role_status(legacy_user_id,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cc_field_permissions (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, role_id BIGINT UNSIGNED NOT NULL, module_code VARCHAR(80) NOT NULL, field_code VARCHAR(120) NOT NULL, can_view TINYINT(1) NOT NULL DEFAULT 0, can_edit TINYINT(1) NOT NULL DEFAULT 0, masked TINYINT(1) NOT NULL DEFAULT 0, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, PRIMARY KEY(id), UNIQUE KEY uq_cc_field_permission(role_id,module_code,field_code)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cc_data_permissions (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, role_id BIGINT UNSIGNED NOT NULL, module_code VARCHAR(80) NOT NULL, scope_type VARCHAR(30) NOT NULL, scope_value VARCHAR(120) NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, PRIMARY KEY(id), UNIQUE KEY uq_cc_data_permission(role_id,module_code,scope_type,scope_value)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cc_system_logs (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, module_code VARCHAR(80) NOT NULL, object_type VARCHAR(80) NULL, object_id VARCHAR(120) NULL, action_code VARCHAR(60) NOT NULL, actor_legacy_user_id INT UNSIGNED NULL, actor_name VARCHAR(190) NULL, ip_hash CHAR(64) NULL, before_json LONGTEXT NULL, after_json LONGTEXT NULL, request_id CHAR(36) NULL, created_at DATETIME NOT NULL, PRIMARY KEY(id), KEY idx_cc_system_log_module(module_code,action_code,created_at), KEY idx_cc_system_log_object(object_type,object_id,created_at), KEY idx_cc_system_log_actor(actor_legacy_user_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
